CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,full_name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('customer','artist','vendor','production','admin')),status TEXT NOT NULL DEFAULT 'active',referral_code TEXT UNIQUE,referred_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS artist_profiles(user_id BIGINT PRIMARY KEY REFERENCES users(id),display_name TEXT NOT NULL,bio TEXT DEFAULT '',genres TEXT[] DEFAULT '{}',portfolio JSONB DEFAULT '[]',average_rating NUMERIC(3,2) DEFAULT 0,completed_jobs INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS services(id BIGSERIAL PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,category TEXT NOT NULL,description TEXT DEFAULT '',price_kobo BIGINT NOT NULL,estimated_days INTEGER DEFAULT 3,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS orders(id BIGSERIAL PRIMARY KEY,customer_id BIGINT REFERENCES users(id),artist_id BIGINT REFERENCES users(id),service_id BIGINT REFERENCES services(id),brief TEXT NOT NULL,status TEXT DEFAULT 'submitted',amount_kobo BIGINT NOT NULL,payment_reference TEXT UNIQUE,delivery_object_key TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ratings(id BIGSERIAL PRIMARY KEY,order_id BIGINT UNIQUE REFERENCES orders(id),customer_id BIGINT REFERENCES users(id),artist_id BIGINT REFERENCES users(id),score INTEGER CHECK(score BETWEEN 1 AND 5),review TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS vendor_retainerships(id BIGSERIAL PRIMARY KEY,vendor_id BIGINT REFERENCES users(id),status TEXT DEFAULT 'pending',start_date DATE,end_date DATE,terms JSONB DEFAULT '{}');
CREATE TABLE IF NOT EXISTS referral_events(id BIGSERIAL PRIMARY KEY,referrer_id BIGINT REFERENCES users(id),referred_user_id BIGINT UNIQUE REFERENCES users(id),qualifying_order_id BIGINT REFERENCES orders(id),qualified_at TIMESTAMPTZ,reward_status TEXT DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS payment_events(id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES orders(id),provider TEXT NOT NULL,provider_reference TEXT UNIQUE NOT NULL,amount_kobo BIGINT NOT NULL,status TEXT DEFAULT 'initialized',raw_event JSONB DEFAULT '{}');
CREATE TABLE IF NOT EXISTS subscriptions(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),plan_code TEXT NOT NULL,status TEXT DEFAULT 'pending',provider_reference TEXT,current_period_end TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS orders_customer_created_idx ON orders(customer_id,created_at DESC);